// Generated by `just generate` from `src/plugins/claudetto/slices/usercheck/domain/usercheck.ts`. Edit the source and run `just generate`.
// The pure parts of the `usercheck` slice.
// When a permission check denies a call, a check of the work can stay open, and only the user can run it.
// The `Stop` hook then makes sure that the reply gives the user a `!` command.
// The test is on Markdown syntax, a code item or a code block line that starts with `!`, so it works in each language of the reply.

import { MAX_CALL_CHARS, MAX_NAMED_CALLS } from "../limits.ts";
import { BLOCK_REASON } from "../prompts.ts";

/** The fields of a `PermissionDenied` event that the slice reads. */
export interface DeniedEvent {
  tool_name?: unknown;
  tool_input?: unknown;
}

/** The label of one denied call: the first line of a `Bash` command, or the name of the tool. */
export const deniedCall = (e: DeniedEvent): string => {
  const tool = String(e.tool_name ?? "");
  const input = e.tool_input as { command?: unknown } | null | undefined;
  const command =
    typeof input?.command === "string" ? input.command.trim() : "";
  const label = (command ? command.split("\n")[0] : undefined) ?? tool;
  return label.length > MAX_CALL_CHARS
    ? `${label.slice(0, MAX_CALL_CHARS)}…`
    : label;
};

/** A user command in the text of a code item or a code block line: a `!` and then a word. */
const USER_TEXT = /^!\s*\S/;

/** The fence that a line opens, such as "```" or "~~~~", or undefined when the line opens none. */
const fenceOf = (line: string): string | undefined =>
  /^ {0,3}(`{3,}|~{3,})/.exec(line)?.[1];

/** True when a line closes the fence `open`: the same character, at least as long, and nothing after it. */
const closes = (line: string, open: string): boolean =>
  new RegExp(`^ {0,3}\\${open[0]}{${open.length},}\\s*$`).test(line);

/** True when a code item in `line` starts with `!`. A run of backticks closes at the next run of the same length. */
const itemInLine = (line: string): boolean => {
  const runs = [...line.matchAll(/`+/g)];
  for (let i = 0; i < runs.length; i++) {
    const open = runs[i] as RegExpMatchArray;
    const end = runs.findIndex(
      (r, k) => k > i && r[0].length === open[0].length,
    );
    if (end < 0) continue;
    const close = runs[end] as RegExpMatchArray;
    const text = line.slice(
      (open.index as number) + open[0].length,
      close.index,
    );
    if (USER_TEXT.test(text.trim())) return true;
    i = end;
  }
  return false;
};

/** True when the reply has a code item that starts with `!`, or a line of a fenced code block that does. Fences of "```" and "~~~" pair in order, as in Markdown. */
const hasUserLine = (reply: string): boolean => {
  let open: string | undefined;
  for (const line of reply.split("\n")) {
    if (open !== undefined) {
      if (closes(line, open)) open = undefined;
      else if (USER_TEXT.test(line.trim())) return true;
      continue;
    }
    open = fenceOf(line);
    if (open === undefined && itemInLine(line)) return true;
  }
  return false;
};

/** True when the reply gives the user a `!` command. */
export const hasUserCommand = (reply: unknown): boolean =>
  typeof reply === "string" && hasUserLine(reply);

/** The block reason of a `Stop` with denied calls and no `!` command in the reply. */
export const blockReason = (calls: readonly string[]): string => {
  const named = calls.slice(0, MAX_NAMED_CALLS).map((c) => `\`${c}\``);
  const others = calls.length - named.length;
  return BLOCK_REASON({
    which: calls.length === 1 ? "this call" : "these calls",
    named: named.join(", "),
    more: others > 0 ? `, and ${others} more` : "",
  });
};
